{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create Or Replace Table MapleMonk.Habanero_DB_Inventory_Fact_items as WITH Inventory AS ( SELECT location, CAST(DATETIME_ADD(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', Report_Generated_Date), INTERVAL 1 DAY) AS DATE) AS DATA_FETCH_DATE, REPLACE(REPLACE(SKU,\'\\'\',\'\'),\'`\',\'\') AS SKU, UPPER(Product_Name) AS PRODUCTNAME, CAST(Available_Quantity AS INT64) AS Available_Quantity, Undispatched_Unassigned_Quantity FROM `Maplemonk.habanero_db_inventory_snapshot` QUALIFY ROW_NUMBER() OVER ( PARTITION BY location, Company_Token, SKU, CAST(DATA_FETCH_DATE AS DATE) ORDER BY DATA_FETCH_DATE ) = 1 ), PO_Data_l AS ( SELECT Warehouse_Name, CAST(CAST(order_date AS TIMESTAMP) AS DATE) AS Order_Date, REPLACE(REPLACE(master_sku,\'\\'\',\'\'),\'`\',\'\') AS SKU, SUM(IFNULL(suborder_quantity,0)) AS suborder_quantity FROM MAPLEMONK.habanero_EasyEcom_FACT_ITEMS WHERE UPPER(marketplace) != \'B2B\' GROUP BY 1,2,3 ), PO_Data as ( SELECT COALESCE(i.location, p.Warehouse_Name) AS Warehouse_Name, COALESCE(i.DATA_FETCH_DATE, p.Order_Date) AS Order_Date, COALESCE(i.SKU, p.SKU) AS SKU, ifnull(i.Available_Quantity,0) as Available_Quantity, ifnull(p.suborder_quantity,0) as suborder_quantity FROM Inventory i FULL OUTER JOIN PO_Data_l p ON trim(lower(i.location)) = trim(lower(p.Warehouse_Name)) AND i.DATA_FETCH_DATE = p.Order_Date AND trim(lower(i.SKU)) = trim(lower(p.SKU)) ), last_days as ( SELECT a.Warehouse_Name, a.SKU, a.Order_Date, a.suborder_quantity, a.Available_Quantity, COALESCE(SUM(b.suborder_quantity),0) AS last_d_sum FROM PO_Data a LEFT JOIN PO_Data b ON a.Warehouse_Name = b.Warehouse_Name AND a.SKU = b.SKU AND Date_diff(b.Order_Date,current_date(),day) = 1 GROUP BY 1,2,3,4,5 ), last_7_days as ( SELECT a.Warehouse_Name, a.SKU, a.Order_Date, a.suborder_quantity, a.Available_Quantity, a.last_d_sum, COALESCE(SUM(b.suborder_quantity),0) AS last_7d_sum FROM last_days a LEFT JOIN last_days b ON a.Warehouse_Name = b.Warehouse_Name AND a.SKU = b.SKU AND b.Order_Date BETWEEN DATE_SUB(a.Order_Date, INTERVAL 6 DAY) AND a.Order_Date GROUP BY 1,2,3,4,5,6 ), last_28_days as ( SELECT a.Warehouse_Name, a.SKU, a.Order_Date, a.suborder_quantity, a.Available_Quantity, a.last_7d_sum, a.last_d_sum, COALESCE(SUM(b.suborder_quantity),0) AS last_28d_sum FROM last_7_days a LEFT JOIN last_7_days b ON a.Warehouse_Name = b.Warehouse_Name AND a.SKU = b.SKU AND b.Order_Date BETWEEN DATE_SUB(a.Order_Date, INTERVAL 27 DAY) AND a.Order_Date GROUP BY 1,2,3,4,5,6,7 ), Current_days as ( SELECT Warehouse_Name, REPLACE(REPLACE(master_sku,\'\\'\',\'\'),\'`\',\'\') AS SKU, SUM(IFNULL(suborder_quantity,0)) AS current_Month_quantity, max(EXTRACT(DAY FROM CURRENT_DATE)) as Day FROM MAPLEMONK.habanero_EasyEcom_FACT_ITEMS WHERE UPPER(marketplace) != \'B2B\' and last_day(current_date()) = last_day(CAST(CAST(order_date AS TIMESTAMP) AS DATE)) GROUP BY 1,2 ) Select po.*, last_7d_sum, last_28d_sum, last_d_sum, current_Month_quantity, Day from PO_Data po left join last_28_days ld on trim(lower(po.Warehouse_Name)) = trim(lower(ld.Warehouse_Name)) and po.Order_Date = ld.Order_Date and lower(po.sku) = lower(ld.SKU) left join Current_days ld1 on trim(lower(po.Warehouse_Name)) = trim(lower(ld1.Warehouse_Name)) and lower(po.sku) = lower(ld1.SKU) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            